/**
 * Dates as a reader sees them. Records carry EDTF as catalogued (`1938~`, `1898/1905`, `189X`);
 * search hits carry a year range.
 */

const MONTHS = [
  'January',
  'February',
  'March',
  'April',
  'May',
  'June',
  'July',
  'August',
  'September',
  'October',
  'November',
  'December',
];

/** One EDTF date (no interval): `1938`, `1938-05`, `1938-05-12`, `189X`, `19XX`, with `~ ? %`. */
function readableDate(value: string): string {
  const match = /^(-?)(\d{2}[\dX]{2})(?:-(\d{2}))?(?:-(\d{2}))?([~?%]?)$/.exec(value);
  if (match === null) return value;
  const [, minus = '', year = '', month, day, qualifier = ''] = match;
  let text: string;
  if (year.endsWith('XX')) text = `${year.slice(0, 2)}00s`;
  else if (year.endsWith('X')) text = `${year.slice(0, 3)}0s`;
  else text = String(Number(year));
  if (minus === '-') text = `${text} BCE`;
  const monthName = month !== undefined ? MONTHS[Number(month) - 1] : undefined;
  if (monthName !== undefined) {
    text =
      day !== undefined ? `${monthName} ${String(Number(day))}, ${text}` : `${monthName} ${text}`;
  }
  switch (qualifier) {
    case '~':
      return `about ${text}`;
    case '?':
      return `${text}?`;
    case '%':
      return `about ${text}?`;
    default:
      return text;
  }
}

/** `1938~` → `about 1938`, `1898/1905` → `1898–1905`, `../1900` → `before 1900`, `189X` → `1890s`. */
export function readableEdtf(value: string): string {
  const edtf = value.trim();
  const slash = edtf.indexOf('/');
  if (slash === -1) return readableDate(edtf);
  const start = edtf.slice(0, slash);
  const end = edtf.slice(slash + 1);
  const open = (part: string) => part === '' || part === '..';
  if (open(start) && open(end)) return edtf;
  if (open(start)) return `before ${readableDate(end)}`;
  if (open(end)) return `after ${readableDate(start)}`;
  return `${readableDate(start)}–${readableDate(end)}`;
}

/** A search hit's years: `1898`, `1898–1905`, or undefined when the work is undated. */
export function yearsLabel(
  yearStart: number | null | undefined,
  yearEnd: number | null | undefined,
): string | undefined {
  const start = yearStart ?? yearEnd;
  const end = yearEnd ?? yearStart;
  if (start === null || start === undefined || end === null || end === undefined) return undefined;
  return start === end ? String(start) : `${String(start)}–${String(end)}`;
}

/** A year as read: `1898`, or `3650 BCE` for `-3650`. */
function yearText(year: number): string {
  return year < 0 ? `${String(-year)} BCE` : String(year);
}

/**
 * A year filter value as read: the decade `1890-1899` → `1890s`, the BCE decade `-3650--3641` →
 * `3650–3641 BCE`, other ranges as `1890–1910` or `20 BCE–1900`, a year `-3500` → `3500 BCE`.
 */
export function decadeLabel(value: string): string {
  const match = /^(-?\d{1,4})(?:-(-?\d{1,4}))?$/.exec(value);
  if (match === null) return value;
  const [, from = '', to] = match;
  const start = Number(from);
  if (to === undefined) return yearText(start);
  const end = Number(to);
  if (start >= 0 && start % 10 === 0 && end === start + 9) return `${String(start)}s`;
  if (end < 0) return `${String(-start)}–${String(-end)} BCE`;
  return `${yearText(start)}–${yearText(end)}`;
}
