import { createContext, useContext } from 'react';
import type { SiteConfig } from '../config/config.js';
import type { Site } from '../config/site.js';
import type { Brand } from '../theme/theme.js';

/** What the deployment told the site at startup: `config.json`, `site.json` and `theme.json`. */
export interface SiteServices {
  readonly config: SiteConfig;
  readonly site: Site;
  /** Name, short name and logo from `theme.json` (the default brand without one). */
  readonly brand: Brand;
}

export const ServicesContext = createContext<SiteServices | undefined>(undefined);

export function useServices(): SiteServices {
  const services = useContext(ServicesContext);
  if (services === undefined) throw new Error('useServices outside <ServicesContext>');
  return services;
}

export function useConfig(): SiteConfig {
  return useServices().config;
}

export function useSite(): Site {
  return useServices().site;
}

export function useBrand(): Brand {
  return useServices().brand;
}
