import { useMemo } from 'react';
import { useConfig } from '../app/context.js';
import type { SiteConfig } from '../config/config.js';

/** URLs on the IIIF services the deployment names in `config.json`. */
export interface IiifUrls {
  /** A file set's image scaled to fit in `size`×`size` pixels (IIIF Image API 3.0 `!w,h`). */
  readonly image: (fileSetId: string, size: number) => string;
  /** A file set's `info.json`, for deep zoom. */
  readonly info: (fileSetId: string) => string;
  /** A public work's IIIF Presentation 3.0 manifest on the Public API. */
  readonly manifest: (workId: string) => string;
  /** A public collection's IIIF Presentation 3.0 collection on the Public API. */
  readonly collection: (collectionId: string) => string;
}

export function iiifUrls(config: SiteConfig): IiifUrls {
  const image = config.iiifImageBaseUrl;
  return {
    image: (fileSetId, size) =>
      `${image}/${encodeURIComponent(fileSetId)}/full/!${String(size)},${String(size)}/0/default.jpg`,
    info: (fileSetId) => `${image}/${encodeURIComponent(fileSetId)}/info.json`,
    manifest: (workId) => `${config.apiBaseUrl}/iiif/manifests/${encodeURIComponent(workId)}`,
    collection: (collectionId) =>
      `${config.apiBaseUrl}/iiif/collections/${encodeURIComponent(collectionId)}`,
  };
}

export function useIiif(): IiifUrls {
  const config = useConfig();
  return useMemo(() => iiifUrls(config), [config]);
}
