import { ScanSearchIcon } from 'lucide-react';
import { Link } from 'react-router';
import type { WorkHit } from '../api/client.js';
import { IiifImage } from './IiifImage.js';
import { Badge } from '@/components/ui/badge';
import { cn } from '@/lib/utils';

/**
 * Search with image results (S14b): the API matches works by what their images show as well as
 * by their records, and says which image matched. A hit shows that image, which for a book is
 * the page with the lion rather than its cover, and says so when the record itself did not
 * match, since nothing in the title or facts then explains the result. Every page that matched
 * is listed under the hit, each opening the work at that page (captain, 2026-10-28: "if two
 * pages of a work match, show both").
 */

/** The work page, at the page that matched best when the search matched its images. */
export function hitLink(work: WorkHit): string {
  const page = work.match?.images?.[0]?.page;
  return page !== undefined && page !== null && page > 1
    ? `/works/${work.id}?page=${String(page)}`
    : `/works/${work.id}`;
}

/**
 * The pages of a hit that matched the query, nearest first, each a link to that page; nothing
 * when fewer than two matched (the hit's own image is then the one).
 */
export function MatchedPages({
  work,
  className,
}: {
  readonly work: WorkHit;
  readonly className?: string;
}) {
  const images = work.match?.images ?? [];
  if (images.length < 2) return null;
  const count = Math.max(work.match?.imageCount ?? images.length, images.length);
  const label = `${String(count)} matching ${count === 1 ? 'page' : 'pages'}`;
  return (
    <div className={cn('mt-2', className)}>
      <p className="text-[12px] text-muted-foreground">{label}</p>
      <ul aria-label={label} className="mt-1 flex flex-wrap gap-1.5">
        {images.map((image) => (
          <li key={image.fileSetId}>
            <Link
              to={
                image.page !== null && image.page > 1
                  ? `/works/${work.id}?page=${String(image.page)}`
                  : `/works/${work.id}`
              }
              aria-label={image.page !== null ? `Page ${String(image.page)}` : 'Matching image'}
              className="block size-11 overflow-hidden rounded-md bg-muted ring-1 ring-border hover:ring-2 hover:ring-primary/60 focus-visible:ring-3 focus-visible:ring-ring/50 focus-visible:outline-none"
            >
              <IiifImage fileSetId={image.fileSetId} size={120} className="size-full" />
            </Link>
          </li>
        ))}
        {count > images.length && (
          <li className="grid h-11 place-items-center px-1 text-[12px] text-muted-foreground">
            +{String(count - images.length)}
          </li>
        )}
      </ul>
    </div>
  );
}

/** The image a hit shows: the one that matched the query, else the representative image. */
export function hitImageId(work: WorkHit): string | null {
  return work.match?.imageFileSetId ?? work.representativeFileSetId;
}

/** The query matched the work's picture but nothing in its record. */
export function matchedByImageOnly(work: WorkHit): boolean {
  const match = work.match;
  return match !== undefined && match !== null && match.image !== null && match.keyword === null;
}

/** `onImage`: laid over a picture, so opaque to stay readable on any image. */
export function ImageMatchBadge({
  onImage = false,
  className,
}: {
  readonly onImage?: boolean;
  readonly className?: string;
}) {
  return (
    <Badge
      variant="info"
      className={cn(onImage && 'bg-background/95 shadow-sm ring-border', className)}
    >
      <ScanSearchIcon aria-hidden="true" />
      Matched by image
    </Badge>
  );
}
