import createClient, { type Client } from 'openapi-fetch';
import type { components, paths } from './schema.js';

/**
 * The Public API client: `openapi-fetch` typed by `schema.d.ts`, which `npm run api:update`
 * generates from the vendored `public-api.openapi.json` (a test fails while they disagree). The
 * API is anonymous and allows any origin, so requests are plain cross-origin GETs.
 */

export type Schemas = components['schemas'];

/**
 * The optional Public API additions (slice B1: hit creators, genres and snippets, collection
 * thumbnails; S14b: image matches) are in the document but may be missing from a deployed API
 * that predates them, so the site's types mark them optional and screens show them only when
 * present.
 */
type MaybeMissing<T, K extends keyof T> = Omit<T, K> & Partial<Pick<T, K>>;

/** `images` and `imageCount` came after the first image matches (S14b, 2026-10-28). */
export type SearchMatch = MaybeMissing<Schemas['SearchMatch'], 'images' | 'imageCount'>;
export type ImageMatch = Schemas['ImageMatch'];
export type WorkHit = Omit<
  MaybeMissing<Schemas['WorkHit'], 'creators' | 'genres' | 'snippet' | 'match'>,
  'match'
> & { match?: SearchMatch | null };
export type SearchResults = Omit<
  MaybeMissing<Schemas['SearchResults'], 'contentSearch'>,
  'items'
> & {
  items: WorkHit[];
};
export type ContentSearch = Schemas['ContentSearch'];
export type SearchSort = Schemas['SearchSort'];
export type Snippet = Schemas['Snippet'];
export type Facets = Schemas['Facets'];
export type FacetValue = Schemas['FacetValue'];
export type CollectionRef = Schemas['CollectionRef'];
export type PublicWork = Schemas['PublicWork'];
export type ModsRecord = Schemas['ModsRecord'];
export type PublicCollection = MaybeMissing<Schemas['PublicCollection'], 'thumbnailFileSetIds'>;
export type PublicCollectionPage = Omit<Schemas['PublicCollectionPage'], 'items'> & {
  items: PublicCollection[];
};
export type IiifManifest = Schemas['IiifManifest'];
export type IiifCollection = Schemas['IiifCollection'];
export type Problem = Schemas['Problem'];

export type PublicClient = Client<paths>;

/** Seconds to wait after a 503 when the API's `Retry-After` is unreadable (CORS hides it). */
export const DEFAULT_RETRY_AFTER_SECONDS = 15;

/** A non-2xx answer, carrying the RFC 9457 problem when the API sent one. */
export class ApiError extends Error {
  override readonly name = 'ApiError';
  constructor(
    readonly status: number,
    readonly problem: Problem | undefined,
    /** From `Retry-After` on a 503, in seconds. */
    readonly retryAfter?: number,
  ) {
    super(problem?.detail ?? problem?.title ?? `HTTP ${String(status)}`);
  }
}

/** The database is resuming from auto-pause (about 15 s): the site waits and retries. */
export function isWaking(error: unknown): error is ApiError {
  return error instanceof ApiError && error.status === 503;
}

export function isNotFound(error: unknown): error is ApiError {
  return error instanceof ApiError && error.status === 404;
}

function isProblem(value: unknown): value is Problem {
  return typeof value === 'object' && value !== null && 'type' in value && 'status' in value;
}

function retryAfterOf(response: Response): number | undefined {
  if (response.status !== 503) return undefined;
  const seconds = Number(response.headers.get('retry-after') ?? Number.NaN);
  return Number.isFinite(seconds) && seconds > 0 ? seconds : DEFAULT_RETRY_AFTER_SECONDS;
}

export interface PublicClientOptions {
  /** `config.json`'s `apiBaseUrl`. */
  readonly baseUrl: string;
  readonly fetch?: (input: Request) => Promise<Response>;
}

export function createPublicClient(options: PublicClientOptions): PublicClient {
  return createClient<paths>({
    baseUrl: options.baseUrl,
    ...(options.fetch !== undefined ? { fetch: options.fetch } : {}),
  });
}

/** The data of an `openapi-fetch` result, or an `ApiError` for anything else. */
export function unwrap<T>(result: { data?: T; error?: unknown; response: Response }): T {
  if (result.response.ok) return result.data as T;
  throw new ApiError(
    result.response.status,
    isProblem(result.error) ? result.error : undefined,
    retryAfterOf(result.response),
  );
}
