import { Link } from 'react-router';
import type { WorkHit } from '../api/client.js';
import { yearsLabel } from '../lib/dates.js';
import { IiifImage } from './IiifImage.js';
import { hitImageId, hitLink, ImageMatchBadge, matchedByImageOnly } from './ImageMatch.js';
import { cn } from '@/lib/utils';

/** A work's title as shown in lists; the API sends null for an untitled record. */
export function workTitle(work: { readonly title: string | null }): string {
  return work.title ?? 'Untitled';
}

/**
 * The facts under a title in lists: years and the first genre, or the first collection when the
 * API sends no genres (before the B1 additions).
 */
export function workFacts(work: WorkHit): string {
  return [yearsLabel(work.yearStart, work.yearEnd), work.genres?.[0] ?? work.collections[0]?.title]
    .filter((fact) => fact !== undefined)
    .join(' · ');
}

/**
 * A search hit, a collection member or a related work in a grid: the representative image (or
 * the one that matched the search), the serif title and its facts, linking to the work page.
 */
export function WorkCard({
  work,
  aspect = 'aspect-[4/3]',
  className,
}: {
  readonly work: WorkHit;
  /** The image box (`aspect-[4/3]`, `aspect-[3/4]` for posters, `aspect-square`). */
  readonly aspect?: string;
  readonly className?: string;
}) {
  const facts = workFacts(work);
  return (
    <Link
      to={hitLink(work)}
      className={cn(
        'group block min-w-0 rounded-lg focus-visible:ring-3 focus-visible:ring-ring/50 focus-visible:outline-none',
        className,
      )}
    >
      <div
        className={cn('relative overflow-hidden rounded-lg bg-muted ring-1 ring-border', aspect)}
      >
        <IiifImage
          fileSetId={hitImageId(work)}
          size={600}
          className="size-full transition group-hover:scale-[1.02] motion-reduce:transition-none motion-reduce:group-hover:scale-100"
        />
        {matchedByImageOnly(work) && (
          <ImageMatchBadge onImage className="absolute bottom-2 left-2" />
        )}
      </div>
      <p className="mt-2.5 line-clamp-2 font-heading text-[15px] leading-snug font-semibold text-foreground decoration-border underline-offset-4 group-hover:underline">
        {workTitle(work)}
      </p>
      {facts !== '' && <p className="mt-0.5 truncate text-[13px] text-muted-foreground">{facts}</p>}
    </Link>
  );
}

/** A grid of `WorkCard`-sized placeholders while results load. */
export function WorkGridSkeleton({ count = 8 }: { readonly count?: number }) {
  return (
    <div
      aria-hidden="true"
      className="grid grid-cols-2 gap-x-5 gap-y-7 sm:grid-cols-3 lg:grid-cols-4"
    >
      {Array.from({ length: count }, (_, index) => (
        <div key={index}>
          <div className="aspect-[4/3] animate-pulse rounded-lg bg-muted motion-reduce:animate-none" />
          <div className="mt-2.5 h-3.5 w-4/5 rounded bg-muted" />
          <div className="mt-1.5 h-3 w-1/2 rounded bg-muted/70" />
        </div>
      ))}
    </div>
  );
}
