import type { VariantProps } from 'class-variance-authority';
import type { ComponentProps, ReactNode } from 'react';
import { Link } from 'react-router';
import type { SiteLink } from '../config/site.js';
import { buttonVariants } from '@/components/ui/button';
import { cn } from '@/lib/utils';

/** An in-site link that looks like a button ("All collections"): role `link`, not `button`. */
export function ButtonLink({
  variant = 'outline',
  size = 'default',
  className,
  ...props
}: ComponentProps<typeof Link> & VariantProps<typeof buttonVariants>) {
  return <Link className={cn(buttonVariants({ variant, size }), className)} {...props} />;
}

/** The underline that marks a link in running text and record values. */
export const TEXT_LINK =
  'text-primary-text underline decoration-primary-text/30 underline-offset-4 hover:decoration-primary-text focus-visible:rounded-sm focus-visible:ring-3 focus-visible:ring-ring/50 focus-visible:outline-none';

/** An in-site link in running text and metadata values ("Yellowstone", a subject). */
export function TextLink({ className, ...props }: ComponentProps<typeof Link>) {
  return <Link className={cn(TEXT_LINK, className)} {...props} />;
}

/**
 * A link from `site.json` (footer, about page): site paths go through the router, `https:` and
 * `mailto:` addresses are plain anchors (external ones open in place, without the referrer).
 */
export function SiteAnchor({
  link,
  className,
  children,
}: {
  readonly link: SiteLink;
  readonly className?: string;
  readonly children?: ReactNode;
}) {
  const content = children ?? link.label;
  if (link.href.startsWith('/')) {
    return (
      <Link to={link.href} className={className}>
        {content}
      </Link>
    );
  }
  return (
    <a
      href={link.href}
      className={className}
      {...(link.href.startsWith('https:') ? { rel: 'noreferrer' } : {})}
    >
      {content}
    </a>
  );
}
