import { ArrowRightIcon } from 'lucide-react';
import type { ReactNode } from 'react';
import { Link } from 'react-router';
import { cn } from '@/lib/utils';

/** The page column: 1240 px wide at most, with the gutters of the header and footer. */
export function Container({
  className,
  children,
}: {
  readonly className?: string;
  readonly children: ReactNode;
}) {
  return (
    <div className={cn('mx-auto w-full max-w-[1240px] px-4 sm:px-6 lg:px-8', className)}>
      {children}
    </div>
  );
}

/** The page's one serif `<h1>`, with an optional line under it. */
export function PageTitle({
  children,
  description,
  className,
}: {
  readonly children: ReactNode;
  readonly description?: ReactNode;
  readonly className?: string;
}) {
  return (
    <div className={className}>
      <h1 className="font-heading text-3xl leading-tight font-semibold tracking-tight text-foreground md:text-[34px]">
        {children}
      </h1>
      {description !== undefined && (
        <p className="mt-2 max-w-2xl text-base text-muted-foreground">{description}</p>
      )}
    </div>
  );
}

/** A section's serif `<h2>`, with an optional subtitle and a "see all" link on the right. */
export function SectionHeading({
  children,
  sub,
  link,
  id,
}: {
  readonly children: ReactNode;
  readonly sub?: ReactNode;
  readonly link?: { readonly text: string; readonly to: string };
  readonly id?: string;
}) {
  return (
    <div className="flex items-end justify-between gap-4">
      <div>
        <h2 id={id} className="font-heading text-[22px] font-semibold tracking-tight">
          {children}
        </h2>
        {sub !== undefined && <p className="mt-0.5 text-sm text-muted-foreground">{sub}</p>}
      </div>
      {link !== undefined && (
        <Link
          to={link.to}
          className="inline-flex shrink-0 items-center gap-1 text-sm font-medium text-primary-text hover:underline"
        >
          {link.text}
          <ArrowRightIcon aria-hidden="true" className="size-4" />
        </Link>
      )}
    </div>
  );
}
