import { keepPreviousData, useQuery } from '@tanstack/react-query';
import { createContext, useContext } from 'react';
import {
  ApiError,
  isWaking,
  unwrap,
  type PublicClient,
  type PublicCollection,
  type SearchResults,
  type SearchSort,
} from './client.js';
import type { paths } from './schema.js';

/**
 * TanStack Query hooks over the Public API, shared by every screen. Answers are cached per key;
 * a 503 (the database resuming) is retried after its `Retry-After` while the screen shows the
 * "waking up" state (`QueryState`), and other 4xx answers are not retried.
 */

export const ApiContext = createContext<PublicClient | undefined>(undefined);

export function useApi(): PublicClient {
  const client = useContext(ApiContext);
  if (client === undefined) throw new Error('useApi outside <ApiContext>');
  return client;
}

/** Facet filters, as `GET /search` takes them (`f.*`); several values in one facet are ANDed. */
export interface SearchFilters {
  readonly subject?: readonly string[] | undefined;
  readonly name?: readonly string[] | undefined;
  readonly genre?: readonly string[] | undefined;
  /** ISO 639-2/B codes, e.g. `eng`. */
  readonly language?: readonly string[] | undefined;
  /** Collection ids. */
  readonly collection?: readonly string[] | undefined;
  /** A year or range such as `1890-1899`. */
  readonly year?: string | undefined;
}

export interface SearchParams {
  /** Keywords in web search syntax; omit to browse. */
  readonly q?: string | undefined;
  readonly filters?: SearchFilters | undefined;
  readonly sort?: SearchSort | undefined;
  /** Page size, 1-100 (API default 20). */
  readonly limit?: number | undefined;
  /** Values per term facet, 1-100 (API default 20). */
  readonly facetLimit?: number | undefined;
  readonly cursor?: string | undefined;
}

export const keys = {
  search: (params: SearchParams) => ['search', params] as const,
  work: (id: string) => ['works', id] as const,
  manifest: (id: string) => ['manifests', id] as const,
  collections: ['collections'] as const,
  collection: (id: string) => ['collections', id] as const,
};

/** 503s are retried for about three minutes; other API errors (4xx, 500) not at all. */
const MAX_WAKING_RETRIES = 12;

export function shouldRetry(failureCount: number, error: unknown): boolean {
  if (isWaking(error)) return failureCount < MAX_WAKING_RETRIES;
  if (error instanceof ApiError) return false;
  // Network failures (TypeError): a few quick retries.
  return failureCount < 3;
}

export function retryDelay(attempt: number, error: unknown): number {
  if (isWaking(error) && error.retryAfter !== undefined) return error.retryAfter * 1000;
  return Math.min(1000 * 2 ** attempt, 8000);
}

const nonEmpty = (values: readonly string[] | undefined) =>
  values !== undefined && values.length > 0 ? [...values] : undefined;

export type SearchQuery = NonNullable<paths['/search']['get']['parameters']['query']>;

/** `GET /search` query parameters for `params`, leaving out what is unset. */
export function searchQuery(params: SearchParams): SearchQuery {
  const f = params.filters ?? {};
  const query = {
    q: params.q?.trim() === '' ? undefined : params.q?.trim(),
    'f.subject': nonEmpty(f.subject),
    'f.name': nonEmpty(f.name),
    'f.genre': nonEmpty(f.genre),
    'f.language': nonEmpty(f.language),
    'f.collection': nonEmpty(f.collection),
    'f.year': f.year === '' ? undefined : f.year,
    sort: params.sort,
    limit: params.limit,
    facetLimit: params.facetLimit,
    cursor: params.cursor,
  };
  return Object.fromEntries(Object.entries(query).filter(([, value]) => value !== undefined));
}

export async function fetchSearch(api: PublicClient, params: SearchParams): Promise<SearchResults> {
  return unwrap(await api.GET('/search', { params: { query: searchQuery(params) } }));
}

/** One page of search results with facet counts over every match. */
export function useSearch(params: SearchParams, options: { enabled?: boolean } = {}) {
  const api = useApi();
  return useQuery({
    queryKey: keys.search(params),
    queryFn: () => fetchSearch(api, params),
    placeholderData: keepPreviousData,
    enabled: options.enabled ?? true,
  });
}

/** A public work with its MODS record (for citations and the record view). */
export function useWork(id: string) {
  const api = useApi();
  return useQuery({
    queryKey: keys.work(id),
    queryFn: async () => unwrap(await api.GET('/works/{id}', { params: { path: { id } } })),
  });
}

/** A public work's IIIF Presentation 3.0 manifest: labelled metadata, rights, canvases. */
export function useManifest(id: string) {
  const api = useApi();
  return useQuery({
    queryKey: keys.manifest(id),
    queryFn: async () =>
      unwrap(await api.GET('/iiif/manifests/{id}', { params: { path: { id } } })),
  });
}

/** Every published collection (the API pages them; a library has a handful). */
export function useCollections() {
  const api = useApi();
  return useQuery({
    queryKey: keys.collections,
    queryFn: async () => {
      const all: PublicCollection[] = [];
      let cursor: string | undefined;
      for (let page = 0; page < 20; page += 1) {
        const data = unwrap(
          await api.GET('/collections', {
            params: { query: { limit: 100, ...(cursor !== undefined ? { cursor } : {}) } },
          }),
        );
        all.push(...data.items);
        if (data.nextCursor === null) break;
        cursor = data.nextCursor;
      }
      return all;
    },
    staleTime: 5 * 60_000,
  });
}

export function useCollection(id: string) {
  const api = useApi();
  return useQuery({
    queryKey: keys.collection(id),
    queryFn: async (): Promise<PublicCollection> =>
      unwrap(await api.GET('/collections/{id}', { params: { path: { id } } })),
  });
}
