import { ImageIcon } from 'lucide-react';
import { useState } from 'react';
import { useIiif } from '../api/iiif.js';
import { cn } from '@/lib/utils';

/**
 * A file set's image from the IIIF Image API, scaled to fit `size` pixels and cropped to its box
 * by `className` (`object-cover`); a placeholder when there is no image or it fails to load.
 * `alt` is empty for images next to a visible title.
 */
export function IiifImage({
  fileSetId,
  size = 600,
  alt = '',
  className,
}: {
  readonly fileSetId: string | null | undefined;
  readonly size?: number;
  readonly alt?: string;
  readonly className?: string;
}) {
  const iiif = useIiif();
  const [failed, setFailed] = useState<string>();
  if (fileSetId === null || fileSetId === undefined || failed === fileSetId) {
    return (
      <span
        role={alt === '' ? undefined : 'img'}
        aria-label={alt === '' ? undefined : alt}
        className={cn('grid place-items-center bg-muted text-muted-foreground', className)}
      >
        <ImageIcon aria-hidden="true" className="size-6" />
      </span>
    );
  }
  return (
    <img
      src={iiif.image(fileSetId, size)}
      alt={alt}
      loading="lazy"
      decoding="async"
      onError={() => {
        setFailed(fileSetId);
      }}
      className={cn('object-cover', className)}
    />
  );
}
